-- Refresh Anthropic model descriptions that no longer match Anthropic's docs.
--
-- Claude Opus 5.5 was described as an unverified third-party report, but
-- Anthropic released it on 2026-09-22 (https://platform.claude.com/docs/en/models/opus-5-5/overview).
-- Older Claude rows also carried stale "most capable"/"latest" claims after newer
-- models shipped, and several rows held another model's text (Sonnet 4.6-style
-- wording on Claude 3 Sonnet, 3.5 Sonnet, 3.7 Sonnet and Mythos Preview; Sonnet 4.5
-- text on the Sonnet 4.6 dash slug; Opus 4 text on Opus 4.1).
-- Descriptions only state facts from Anthropic's model docs or the previous text;
-- lifecycle (status/dates) is intentionally not changed here.

-- Guarded on the description observed during the 2026-10-12 audit, so a newer
-- admin edit is never overwritten. Row-level history is recorded by the
-- catalogue_row_history trigger on public.v2_models.
with fixes (model_slug, old_description, new_description) as (
values
  ($d$anthropic/claude-opus-5.5$d$::text, $d$Claude Opus 5.5 is a preview catalogue entry based on an unverified third-party report. Anthropic has not published an official API listing or availability confirmation.$d$::text, $d$Claude Opus 5.5 is Anthropic's model for long-running agentic coding and knowledge work, released on 2026-09-22. It always runs with adaptive thinking (default effort medium), and has a 1M-token context window and 128K-token output limit.$d$::text),
  ($d$anthropic/claude-sonnet-5.5$d$::text, $d$Claude Sonnet 5.5 combines a 1M-token context window and 128K-token output limit with adaptive thinking.$d$::text, $d$Claude Sonnet 5.5 is Anthropic's Sonnet-class model balancing speed and intelligence, released on 2026-09-28. It combines a 1M-token context window and 128K-token output limit with adaptive thinking.$d$::text),
  ($d$anthropic/claude-haiku-5.5$d$::text, $d$Claude Haiku 5.5 supports adaptive thinking, a 1M-token context window, and 128K-token output for high-volume, latency-sensitive work.$d$::text, $d$Claude Haiku 5.5 is Anthropic's fastest current model, released on 2026-10-07, for high-volume, latency-sensitive tasks such as classification, extraction, and routing. It supports adaptive thinking, a 1M-token context window, and 128K-token output.$d$::text),
  ($d$anthropic/claude-fable-5.1$d$::text, $d$Claude Fable 5.1 is Anthropic's successor to Claude Fable 5. It is currently available through Phaseo using the direct Anthropic provider.$d$::text, $d$Claude Fable 5.1 is Anthropic's model for demanding reasoning and long-horizon agentic work, and the successor to [Claude Fable 5](/anthropic/claude-fable-5). It always runs with adaptive thinking (default effort high), and has a 1M-token context window and 128K-token output limit.$d$::text),
  ($d$anthropic/claude-opus-5$d$::text, $d$Claude Opus 5 is Anthropic's most capable Opus model for complex reasoning, long-horizon agentic coding, and high-autonomy work. It is available at the same price as Opus 4.8 with a 1M token context window and 128K max output.$d$::text, $d$Claude Opus 5 is an Anthropic Opus-class model for complex reasoning, long-horizon agentic coding, and high-autonomy work, released on 2026-07-24. It has a 1M token context window and 128K max output. [Claude Opus 5.5](/anthropic/claude-opus-5.5) is its successor.$d$::text),
  ($d$anthropic/claude-opus-4.8$d$::text, $d$Claude Opus 4.8 is Anthropic's most capable Opus model for complex reasoning, long-horizon agentic coding, and high-autonomy work. It is available at the same price as Opus 4.7 with a 1M token context window and 128K max output.$d$::text, $d$Claude Opus 4.8 is an Anthropic Opus-class model for complex reasoning, long-horizon agentic coding, and high-autonomy work, released on 2026-05-28. It has a 1M token context window and 128K max output.$d$::text),
  ($d$anthropic/claude-sonnet-5$d$::text, $d$Claude Sonnet 5 is Anthropic's latest Sonnet-class model, released on 2026-06-30 with adaptive thinking enabled by default, a 1M-token context window, and 128k maximum output tokens.$d$::text, $d$Claude Sonnet 5 is an Anthropic Sonnet-class model, released on 2026-06-30 with adaptive thinking enabled by default, a 1M-token context window, and 128k maximum output tokens. [Claude Sonnet 5.5](/anthropic/claude-sonnet-5.5) is its successor.$d$::text),
  ($d$anthropic/claude-fable-5$d$::text, $d$Claude Fable 5 is Anthropic's generally available Mythos-class model for long-horizon coding, autonomous knowledge work, and asynchronous agent workflows. It shares the same underlying model as [Claude Mythos 5](/anthropic/claude-mythos-5) but ships with safeguards for high-risk cyber, biology, and chemistry requests, positioning it as Anthropic's public frontier model above Claude Opus 5 for large codebases, multi-stage debugging, and end-to-end work that can run for hours or days with minimal human check-ins.$d$::text, $d$Claude Fable 5 is Anthropic's generally available Mythos-class model for long-horizon coding, autonomous knowledge work, and asynchronous agent workflows. It shares the same underlying model as [Claude Mythos 5](/anthropic/claude-mythos-5) but ships with safeguards for high-risk cyber, biology, and chemistry requests, for large codebases, multi-stage debugging, and end-to-end work that can run for hours or days with minimal human check-ins. [Claude Fable 5.1](/anthropic/claude-fable-5.1) is its successor.$d$::text),
  ($d$anthropic/claude-opus-4.7$d$::text, $d$Claude Opus 4.7 is the next generation of Anthropic's Opus family, built for long-running, asynchronous agents. It supports up to 1M of input context for long documents, codebases, and agent workflows.$d$::text, $d$Claude Opus 4.7 is an Anthropic Opus-class model released on 2026-04-16, built for long-running, asynchronous agents. It supports up to 1M of input context for long documents, codebases, and agent workflows.$d$::text),
  ($d$anthropic/claude-opus-4.6$d$::text, $d$Claude Opus 4.6 is Anthropic's strongest model for coding and long-running professional tasks. It supports up to 1M of input context for long documents, codebases, and agent workflows.$d$::text, $d$Claude Opus 4.6 is an Anthropic Opus-class model for coding and long-running professional tasks, released on 2026-02-05. It supports up to 1M of input context for long documents, codebases, and agent workflows.$d$::text),
  ($d$anthropic/claude-opus-4.5$d$::text, $d$Claude Opus 4.5 is Anthropic's frontier reasoning model optimized for complex software engineering, agentic workflows, and long-horizon computer use. It supports up to 200K of input context for long documents, codebases, and agent workflows.$d$::text, $d$Claude Opus 4.5 is an Anthropic Opus-class reasoning model released on 2025-11-24, optimized for complex software engineering, agentic workflows, and long-horizon computer use. It supports up to 200K of input context for long documents, codebases, and agent workflows.$d$::text),
  ($d$anthropic/claude-sonnet-4.6$d$::text, $d$Claude Sonnet 4.6 is Anthropic's most capable Sonnet-class model yet, with frontier performance across coding, agents, and professional work. It supports up to 1M of input context for long documents, codebases, and agent workflows.$d$::text, $d$Claude Sonnet 4.6 is an Anthropic Sonnet-class model released on 2026-02-17 for coding, agents, and professional work. It supports up to 1M of input context for long documents, codebases, and agent workflows.$d$::text),
  ($d$anthropic/claude-sonnet-4.5$d$::text, $d$Claude Sonnet 4.5 is Anthropic's most advanced Sonnet model to date, optimized for real-world agents and coding workflows. It supports up to 200K of input context for long documents, codebases, and agent workflows.$d$::text, $d$Claude Sonnet 4.5 is an Anthropic Sonnet-class model released on 2025-09-29, optimized for real-world agents and coding workflows. It supports up to 200K of input context for long documents, codebases, and agent workflows.$d$::text),
  ($d$anthropic/claude-haiku-4.5$d$::text, $d$Claude Haiku 4.5 is Anthropic's fastest and most efficient model, delivering near-frontier intelligence at a fraction of the cost and latency of larger Claude models.$d$::text, $d$Claude Haiku 4.5 is Anthropic's small, fast model, released on 2025-10-15, delivering near-frontier intelligence at a fraction of the cost and latency of larger Claude models.$d$::text),
  ($d$anthropic/claude-opus-4-8$d$::text, $d$Opus 4.8 is the next generation of Anthropic's Opus family, built for long-running, asynchronous agents. Building on the coding and agentic strengths of Opus 4.7, it delivers stronger performance on complex, multi-step tasks and more reliable agentic execution across extended workflows. It is especially effective for asynchronous agent pipelines where tasks unfold over time - large codebases, multi-stage debugging, and end-to-end project orchestration.$d$::text, $d$Claude Opus 4.8 is an Anthropic Opus-class model for complex reasoning, long-horizon agentic coding, and high-autonomy work, released on 2026-05-28. It has a 1M token context window and 128K max output.$d$::text),
  ($d$anthropic/claude-opus-4-7$d$::text, $d$Opus 4.7 is the next generation of Anthropic's Opus family, built for long-running, asynchronous agents. Building on the coding and agentic strengths of Opus 4.6, it delivers stronger performance on complex, multi-step tasks and more reliable agentic execution across extended workflows. It is especially effective for asynchronous agent pipelines where tasks unfold over time - large codebases, multi-stage debugging, and end-to-end project orchestration.$d$::text, $d$Claude Opus 4.7 is an Anthropic Opus-class model released on 2026-04-16, built for long-running, asynchronous agents. It supports up to 1M of input context for long documents, codebases, and agent workflows.$d$::text),
  ($d$anthropic/claude-opus-4-6$d$::text, $d$Claude Opus 4.6 is Anthropic's most powerful model yet and the best coding model in the world.$d$::text, $d$Claude Opus 4.6 is an Anthropic Opus-class model for coding and long-running professional tasks, released on 2026-02-05. It supports up to 1M of input context for long documents, codebases, and agent workflows.$d$::text),
  ($d$anthropic/claude-opus-4-5$d$::text, $d$Claude Opus 4.5 is Anthropic's flagship AI model, celebrated as an industry leader for complex coding, autonomous agent tasks, and deep analysis. It combines extreme reasoning capabilities with high token efficiency, making multi-day engineering projects and routine office tasks drastically faster and more cost-effective$d$::text, $d$Claude Opus 4.5 is an Anthropic Opus-class reasoning model released on 2025-11-24, optimized for complex software engineering, agentic workflows, and long-horizon computer use. It supports up to 200K of input context for long documents, codebases, and agent workflows.$d$::text),
  ($d$anthropic/claude-sonnet-4-6$d$::text, $d$Claude Sonnet 4.6 is Anthropic's best coding model in the world, leading on SWE-bench Verified (77.2%) and OSWorld (61.4%). It delivers sustained autonomous performance on complex tasks for over 30 hoursâup from seven hours for Opus 4âmaintaining focus and reliability throughout the entire software development lifecycle, with enhanced capabilities in tool handling, memory management, and context processing that make it the strongest model for building complex agents.$d$::text, $d$Claude Sonnet 4.6 is an Anthropic Sonnet-class model released on 2026-02-17 for coding, agents, and professional work. It supports up to 1M of input context for long documents, codebases, and agent workflows.$d$::text),
  ($d$anthropic/claude-sonnet-4-5$d$::text, $d$Claude Sonnet 4.5 is Anthropic's best coding model in the world, leading on SWE-bench Verified (77.2%) and OSWorld (61.4%). It delivers sustained autonomous performance on complex tasks for over 30 hoursâup from seven hours for Opus 4âmaintaining focus and reliability throughout the entire software development lifecycle, with enhanced capabilities in tool handling, memory management, and context processing that make it the strongest model for building complex agents.$d$::text, $d$Claude Sonnet 4.5 is an Anthropic Sonnet-class model released on 2025-09-29, optimized for real-world agents and coding workflows. It supports up to 200K of input context for long documents, codebases, and agent workflows.$d$::text),
  ($d$anthropic/claude-opus-4-1$d$::text, $d$Claude Opus 4 is Anthropic's most powerful model yet and the best coding model in the world, leading on SWE-bench (72.5%) and Terminal-bench (43.2%). It delivers sustained performance on long-running tasks that require focused effort and thousands of steps, with the ability to work continuously for several hoursâdramatically outperforming all Sonnet models and significantly expanding what AI agents can accomplish.$d$::text, $d$Claude Opus 4.1 was an updated version of Anthropic's Opus 4, offering improved performance in coding, reasoning, and agentic tasks.$d$::text),
  ($d$anthropic/claude-mythos-preview$d$::text, $d$Claude Mythos Preview is Anthropic's most capable Sonnet-class model yet, with frontier performance across coding, agents, and professional work. This entry tracks a preview release and capabilities may change before general availability.$d$::text, $d$Claude Mythos Preview was the preview release of Anthropic's Mythos-class model, offered through Project Glasswing ahead of general availability. [Claude Mythos 5](/anthropic/claude-mythos-5) is its direct successor.$d$::text),
  ($d$anthropic/claude-3-sonnet$d$::text, $d$Claude 3 Sonnet is Anthropic's most capable Sonnet-class model yet, with frontier performance across coding, agents, and professional work. It supports up to 200K of input context for long documents, codebases, and agent workflows.$d$::text, $d$Claude 3 Sonnet was the mid-tier model in Anthropic's Claude 3 family, balancing intelligence and speed. It supports up to 200K of input context for long documents, codebases, and agent workflows.$d$::text),
  ($d$anthropic/claude-3.5-sonnet-2024-06-20$d$::text, $d$Claude 3.5 Sonnet (2024-06-20) is Anthropic's most capable Sonnet-class model yet, with frontier performance across coding, agents, and professional work.$d$::text, $d$Claude 3.5 Sonnet (2024-06-20) was the first model in Anthropic's Claude 3.5 family, a Sonnet-class model for coding, vision, and agentic tasks.$d$::text),
  ($d$anthropic/claude-3.5-sonnet-2024-10-22$d$::text, $d$Claude 3.5 Sonnet (2024-10-22) is Anthropic's most capable Sonnet-class model yet, with frontier performance across coding, agents, and professional work.$d$::text, $d$Claude 3.5 Sonnet (2024-10-22) was the upgraded Claude 3.5 Sonnet snapshot from Anthropic, with improved coding and tool use.$d$::text),
  ($d$anthropic/claude-3.7-sonnet$d$::text, $d$Claude 3.7 Sonnet is Anthropic's most capable Sonnet-class model yet, with frontier performance across coding, agents, and professional work. It supports up to 200K of input context for long documents, codebases, and agent workflows.$d$::text, $d$Claude 3.7 Sonnet was Anthropic's first hybrid reasoning model, able to respond quickly or use extended thinking. It supports up to 200K of input context for long documents, codebases, and agent workflows.$d$::text),
  ($d$anthropic/claude-3.5-haiku$d$::text, $d$Claude 3.5 Haiku features offers enhanced capabilities in speed, coding accuracy, and tool use. It supports up to 200K of input context for long documents, codebases, and agent workflows.$d$::text, $d$Claude 3.5 Haiku offered enhanced capabilities in speed, coding accuracy, and tool use. It supports up to 200K of input context for long documents, codebases, and agent workflows.$d$::text),
  ($d$anthropic/claude-opus-4.7-fast$d$::text, $d$Fast-mode variant of [Opus 4.7](/anthropic/claude-opus-4.7) - identical capabilities with higher output speed at premium 6x pricing. Learn more in Anthropic's docs: https://platform.claude.com/docs/en/build-with-claude/fast-mode.$d$::text, $d$Opus 4.7 Fast was the fast-mode variant of [Opus 4.7](/anthropic/claude-opus-4.7), with identical capabilities and higher output speed at premium 6x pricing. Learn more in Anthropic's docs: https://platform.claude.com/docs/en/build-with-claude/fast-mode.$d$::text)
), applied as (
  update public.v2_models m
  set description = f.new_description,
      updated_at = now()
  from fixes f
  where m.model_slug = f.model_slug
    and m.description is not distinct from f.old_description
  returning m.model_slug
)
select count(*) as updated_rows, 28 as expected_rows from applied;

-- Claude Opus 5.5 is now confirmed by Anthropic's own docs. Record that in the
-- verification metadata and cite the docs. Family assignment and provider route
-- status are deliberately left untouched.
update public.v2_models
set metadata = jsonb_set(
      jsonb_set(
        metadata,
        '{verification}',
        jsonb_build_object(
          'status', 'partial',
          'checked_at', '2026-10-12T00:00:00Z',
          'notes', 'Identity, release date, context window, output limit and thinking behavior confirmed against Anthropic''s Claude Opus 5.5 model page. Capability flags and provider routes were not re-verified.'
        )
      ),
      '{sources}',
      coalesce(metadata -> 'sources', '[]'::jsonb) || jsonb_build_array(
        jsonb_build_object(
          'kind', 'docs',
          'url', 'https://platform.claude.com/docs/en/models/opus-5-5/overview',
          'notes', null,
          'accessed_at', '2026-10-12T00:00:00Z'
        )
      )
    ),
    updated_at = now()
where model_slug = 'anthropic/claude-opus-5.5'
  and metadata -> 'verification' ->> 'status' = 'unverified';
